#!/bin/sh
# The gateway gets only the env it reads, never the platform's whole .env. GATEWAY_SCRIPT runs another script
# with the same env (scripts/reset-owner.ts, the way back from a lost owner key).
set -e
exec env -i PATH="$PATH" HOME="${HOME:-/root}" NODE_ENV="${NODE_ENV:-production}" \
  ${PORT:+PORT="$PORT"} ${STATE_DIR:+STATE_DIR="$STATE_DIR"} ${WEB_DIR:+WEB_DIR="$WEB_DIR"} ${DATABASE_FILE:+DATABASE_FILE="$DATABASE_FILE"} \
  ${API_KEYS:+API_KEYS="$API_KEYS"} ${GATEWAY_SCRIPT:+GATEWAY_SCRIPT="$GATEWAY_SCRIPT"} ${OAUTH_SIGNING_KEY:+OAUTH_SIGNING_KEY="$OAUTH_SIGNING_KEY"} \
  ${GATEWAY_MASTER_KEY:+GATEWAY_MASTER_KEY="$GATEWAY_MASTER_KEY"} ${OPENROUTER_API_KEY:+OPENROUTER_API_KEY="$OPENROUTER_API_KEY"} ${DISCORD_WEBHOOK_URL:+DISCORD_WEBHOOK_URL="$DISCORD_WEBHOOK_URL"} ${COMPOSIO_API_KEY:+COMPOSIO_API_KEY="$COMPOSIO_API_KEY"} \
  ${GATEWAY_AI_GROUPING_PROVIDER:+GATEWAY_AI_GROUPING_PROVIDER="$GATEWAY_AI_GROUPING_PROVIDER"} ${GATEWAY_AI_GROUPING_BASE_URL:+GATEWAY_AI_GROUPING_BASE_URL="$GATEWAY_AI_GROUPING_BASE_URL"} ${GATEWAY_AI_GROUPING_KEY:+GATEWAY_AI_GROUPING_KEY="$GATEWAY_AI_GROUPING_KEY"} \
  ${GATEWAY_AI_GROUPING_WRITER_MODEL:+GATEWAY_AI_GROUPING_WRITER_MODEL="$GATEWAY_AI_GROUPING_WRITER_MODEL"} ${GATEWAY_AI_GROUPING_DECIDER_MODEL:+GATEWAY_AI_GROUPING_DECIDER_MODEL="$GATEWAY_AI_GROUPING_DECIDER_MODEL"} ${GATEWAY_AI_GROUPING_DECIDER_PROTOCOL:+GATEWAY_AI_GROUPING_DECIDER_PROTOCOL="$GATEWAY_AI_GROUPING_DECIDER_PROTOCOL"} \
  ${GATEWAY_LANGFUSE_URL:+GATEWAY_LANGFUSE_URL="$GATEWAY_LANGFUSE_URL"} ${GATEWAY_LANGFUSE_PUBLIC_KEY:+GATEWAY_LANGFUSE_PUBLIC_KEY="$GATEWAY_LANGFUSE_PUBLIC_KEY"} ${GATEWAY_LANGFUSE_SECRET_KEY:+GATEWAY_LANGFUSE_SECRET_KEY="$GATEWAY_LANGFUSE_SECRET_KEY"} \
  ${GATEWAY_BUILD:+GATEWAY_BUILD="$GATEWAY_BUILD"} ${ACCESS_TEAM:+ACCESS_TEAM="$ACCESS_TEAM"} ${ACCESS_AUD:+ACCESS_AUD="$ACCESS_AUD"} ${PUBLIC_HOST:+PUBLIC_HOST="$PUBLIC_HOST"} \
  ${GATEWAY_TELEMETRY:+GATEWAY_TELEMETRY="$GATEWAY_TELEMETRY"} ${GATEWAY_TELEMETRY_URL:+GATEWAY_TELEMETRY_URL="$GATEWAY_TELEMETRY_URL"} ${DO_NOT_TRACK:+DO_NOT_TRACK="$DO_NOT_TRACK"} ${GATEWAY_INSTALL:+GATEWAY_INSTALL="$GATEWAY_INSTALL"} \
  node_modules/.bin/tsx "${GATEWAY_SCRIPT:-src/server.ts}" "$@"
